// Edit these example values before running. Never add a password here.
return [{ json: {
  baseUrl: 'https://nextcloud.example.invalid',
  version: '15', // '13', '14', '15' or 'main' (development)
  integrationUser: 'integration-user',
  signerEmail: 'signer@example.invalid', // replace with a mailbox YOU control
  signedPdfPath: 'Contracts/synthetic-n8n-signed.pdf', // verified relative WebDAV path, not an ID
  maxAttempts: 20,
  waitSeconds: 30,
  pdfBase64: '', // public, one-page synthetic fixture
} }];

const c = $input.first().json;
if (!['13', '14', '15', 'main'].includes(c.version)) throw new Error('Choose LibreSign 13, 14, 15 or main');
let url;
try { url = new URL(c.baseUrl); } catch { throw new Error('Invalid Nextcloud URL'); }
if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash || url.pathname !== '/') throw new Error('Use an HTTPS Nextcloud origin with no credentials, path or query');
if (url.hostname.endsWith('.invalid') || url.hostname === 'example.com') throw new Error('Replace the placeholder Nextcloud host');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.signerEmail) || /@(?:example\.(?:test|invalid|com|org|net))$/i.test(c.signerEmail)) throw new Error('Use an inbox under your control');
if (!/^[A-Za-z0-9_.@-]+$/.test(c.integrationUser)) throw new Error('Use a simple integration account ID; URL-encode it for DAV');
if (typeof c.signedPdfPath !== 'string' || !c.signedPdfPath || c.signedPdfPath.startsWith('/') || c.signedPdfPath.split('/').some(p => !p || p === '.' || p === '..' || p.includes('\\') || p.includes('?') || p.includes('#'))) throw new Error('Set a verified relative WebDAV PDF path');
if (!Number.isInteger(c.maxAttempts) || c.maxAttempts < 1 || c.maxAttempts > 120) throw new Error('maxAttempts must be 1 to 120');
if (!Number.isInteger(c.waitSeconds) || c.waitSeconds < 5 || c.waitSeconds > 3600) throw new Error('waitSeconds must be 5 to 3600');
if (typeof c.pdfBase64 !== 'string' || !c.pdfBase64.startsWith('JVBERi0')) throw new Error('Provide a base64-encoded synthetic PDF');
const method = { method: 'email', value: c.signerEmail };
if (c.version === '13' || c.version === '14') method.mandatory = 1;
else method.requirement = 'required';
const requestBody = { name: 'Synthetic service agreement', status: 1, file: { name: 'synthetic-n8n.pdf', base64: c.pdfBase64 }, signers: [{ displayName: 'External Test Signer', notify: 0, identifyMethods: [method] }] };
return [{ json: { ...c, baseUrl: url.origin, requestBody } }];

const o = $input.first().json;
if (o?.ocs?.meta?.status !== 'ok' || !o.ocs.data) throw new Error('LibreSign did not accept creation (OCS envelope)');
const { id, uuid } = o.ocs.data;
if (!Number.isSafeInteger(id) || id < 1 || typeof uuid !== 'string' || !uuid) throw new Error('Creation lacks a safe file ID and UUID');
return [{ json: { fileId: id, fileUuid: uuid } }];

const o = $input.first().json;
if (o?.ocs?.meta?.status !== 'ok' || o.ocs.data === undefined || o.ocs.data === null) throw new Error('LibreSign did not accept notification request');
// API acknowledgement is NOT proof of email delivery. Never blindly retry.
return [{ json: { notificationSubmitted: true, deliveryConfirmed: false } }];

const o = $input.first().json;
if (o?.ocs?.meta?.status !== 'ok' || !Array.isArray(o?.ocs?.data?.data)) throw new Error('Status check failed or returned an invalid OCS envelope');
const { fileId, fileUuid } = $('Verify created').first().json;
const row = o.ocs.data.data.find(x => String(x.id) === String(fileId) && x.uuid === fileUuid);
if (!row) throw new Error('File not returned: missing permission, unavailable, or filtered; not proof of deletion');
const status = Number(row.status);
if (![0, 1, 2, 3, 4].includes(status)) throw new Error('Unknown file status; manual reconciliation required');
if (status === 4) throw new Error('Signing request was deleted/terminated');
const attempt = $('Poll attempts').item.json.attempt;
if (status !== 3 && attempt >= $('Prepare request').first().json.maxAttempts) throw new Error('Polling limit reached; reconcile before creating anything again');
return [{ json: { signed: status === 3, status, attempt, fileId, fileUuid } }];

const item = $input.first();
if (!item.binary?.signedPdf) throw new Error('WebDAV did not return a PDF binary');
const bytes = await this.helpers.getBinaryDataBuffer(0, 'signedPdf');
if (bytes.toString('utf8', 0, 5) !== '%PDF-') throw new Error('Authenticated WebDAV response is not a PDF');
const { fileId, fileUuid } = $('Verify created').first().json;
return [{ json: { fileId, fileUuid, downloadedBytes: bytes.length, retrieval: 'authorized WebDAV', cryptographicSignatureVerified: false }, binary: item.binary }];
